import { ChatOpenAI } from '@langchain/openai';
import { ChatPromptTemplate } from '@langchain/core/prompts';
import { StringOutputParser } from '@langchain/core/output_parsers';

const prompt = ChatPromptTemplate.fromMessages([
  ['system', 'You are a tech analyst specializing in {topic}.'],
  ['human', '{input}']
]);
const llm = new ChatOpenAI({ modelName: 'gpt-4o', temperature: 0.7 });
const parser = new StringOutputParser();

const chain = prompt.pipe(llm).pipe(parser);
const response = await chain.invoke({ topic: 'AI', input: 'Explain LCEL' });

import { Document, VectorStoreIndex } from 'llamaindex';

const doc = new Document({ text: 'LlamaIndex simplifies data retrieval for LLMs.' });
const index = await VectorStoreIndex.fromDocuments([doc]);
const queryEngine = index.asQueryEngine({ similarityTopK: 3 });
const response = await queryEngine.query({ query: 'What is LlamaIndex?' });

// CrewAI Sequential Execution Pattern
const agents = [
  { role: 'Business Analyst', task: 'Define BRD and requirements' },
  { role: 'System Architect', task: 'Design database and architecture' },
  { role: 'QA Engineer', task: 'Generate automated test plan' }
];

let accumulatedContext = '';
for (const agent of agents) {
  const output = await runAgent(agent, accumulatedContext);
  accumulatedContext += `\n\n[${agent.role} Output]:\n${output}`;
}

function cosineSimilarity(a: number[], b: number[]): number {
  const dot = a.reduce((sum, val, i) => sum + val * b[i], 0);
  const magA = Math.sqrt(a.reduce((sum, val) => sum + val * val, 0));
  const magB = Math.sqrt(b.reduce((sum, val) => sum + val * val, 0));
  return magA && magB ? dot / (magA * magB) : 0;
}
